      de: ["Erste zertifizierte 'Slow City' Asiens (seit 2007).", "Die Gudeuljangnon-Reisfelder sind ein Weltagrurerbe der FAO.", "Die Insel umfasst eine Fläche von etwa 33,3 Quadratkilometern.", "Beherbergt das Dorf Dangni, bekannt aus dem Film 'Seopyeonje'.", "Es gibt 11 ausgewiesene 'Slow Roads' mit einer Gesamtlänge von 42 km.", "Der Name bedeutet wörtlich 'Immergrüne Insel'."],
      hu: ["Ázsia első minősített 'Lassú Városa' 2007 óta.", "A Gudeuljangnon rizsföldek az FAO világörökségi listáján szerepelnek.", "A sziget területe körülbelül 33,3 négyzetkilométer.", "Itt található Dangni falu, a 'Seopyeonje' című film forgatási helyszíne.", "11 kijelölt 'Lassú Út' található itt, összesen 42 km hosszan.", "A sziget neve szó szerint 'Örökzöld szigetet' jelent."],
      ro: ["Primul „Slow City” certificat din Asia în anul 2007.", "Câmpurile Gudeuljangnon sunt recunoscute ca patrimoniu agricol de către FAO.", "Insula are o suprafață de aproximativ 33,3 kilometri pătrați.", "Găzduiește satul Dangni, locație celebră din filmul „Seopyeonje”.", "Există 11 trasee „Slow Roads” cu o lungime totală de 42 km.", "Numele insulei se traduce literal prin „Insula Mereu Verde”."],
      en: ["Designated as Asia's first 'Slow City' in 2007.", "Gudeuljangnon rice fields are a FAO Globally Important Agricultural Heritage System.", "The island covers an area of approximately 33.3 square kilometers.", "Home to Dangni Village, a famous filming site for the movie 'Seopyeonje'.", "Features 11 designated 'Slow Roads' totaling 42 kilometers in length.", "The name Cheongsando literally means 'Evergreen Island'."],
      es: ["Superficie: 33 km²", "Población: aprox. 2.000", "Punto más alto: Mireukbong (385 m)", "Geoparque Global de la UNESCO desde: 2012", "Temperatura media: 14 °C", "Línea costera: 42 km"],
      pt: ["Superfície: 33 km²", "População: aprox. 2.000", "Ponto mais alto: Mireukbong (385 m)", "Geoparque Global da UNESCO desde: 2012", "Temperatura média: 14 °C", "Linha costeira: 42 km"],
      fr: ["Superficie : 33 km²", "Population : env. 2 000", "Point culminant : Mireukbong (385 m)", "Géoparc mondial de l'UNESCO depuis : 2012", "Température moyenne : 14 °C", "Linéaire côtier : 42 km"],
